body_plain:
על שפת היום יתקדשו חיי יומי
בגן המעלף רשת־טללים שקופה;
בלילה רגז לבי בעב חלומי,
ועתה נפשי גלי זך אפופה;
השמש, כמו חרדה היא לשלומי,
עוד תשהה להוטת־עין ועטופה;
עוד רגע והציתה אש במקומי
לבער סיגים מנשמתי צרופה.

תרע"ט

body_nikkud:
זְכוֹר, עַמִּי, רֵאשִׁית גְּבוּרָה,
יְמֵי בָרָק וּדְבוֹרָה;
זְכוֹר, עַמִּי!

זְכוֹר, עַמִּי, נוֹף מְכוֹרָה,
יִפְעָתָהּ, זִיוָהּ, זָהֳרָהּ;
זְכוֹר, עַמִּי!

זְכוֹר, עַמִּי, שָׂפָה יְקָרָה,
קְדוֹשָׁה, נָאוָה וּבָרָה;
זְכוֹר, עַמִּי!

זְכוֹר, עַמִּי, רֹאשׁ עֲטָרָה
וְהָרֵם אוֹתָהּ מֵעֲפָרָהּ;
זְכוֹר, עַמִּי!

body_plain:
זכור, עמי, ראשית גבורה,
ימי ברק ודבורה;
זכור, עמי!

זכור, עמי, נוף מכורה,
יפעתה, זיוה, זהרה;
זכור, עמי!

זכור, עמי, שפה יקרה,
קדושה, נאוה וברה;
זכור, עמי!

זכור, עמי, ראש עטרה
והרם אותה מעפרה;
זכור, עמי!

body_nikkud:
יט. לרעי כאח לי המוכיח במישור לאנשים הנותנים כתף סוררת אל עם ה' בעזבם את תורתו, ואת סכלותם ואת רוע לבבם הראה נגד כל ישראל ונגד השמש

אִישׁ מִלְחָמוֹת! תָּעִיר קִנְאָה וָזַעַם
לִפְנֵי אוֹיֵב; עָלָיו תִּתְגַּבֵּר, נֵצַח!
מִפַּחַד לֹא תֵחַת, תִּשְׂחַק לָרֶצַח
עָלָיו תַּרְנִין אַשְׁפָּה כִּתְרוּעַת רַעַם.

לִקְרַאת נֶשֶׁק תֵּצֵא, וְּכהוֹלֶם פָּעַם
הַכֵּה תַכֶּה תִּמְחַץ רֹאשׁ חִזְקֵי מֵצַח;
יַאְדִּימוּ כַתּוֹלָע, יֵבֹשׁוּ נֶצַח,
כִּי הֵמִירוּ חֻקָּם, וַיְשַׁנּוּ טַעַם.

נֹפֶת וּדְבַשׁ תִּטֹּפְנָה שִׁפְתוֹתֶיךָ;
וּלְפִי בוֹזֵי אֵל חַי מַחְסֹם שָׁמַרְתָּ;
גָּדוֹל עָשִׂיתָ לָךְ שֵׁם תִּפְאַרְתֶּךָ.

עַל בָּמוֹתָם תִּדְרֹךְ, תִּרְדֹּף קָמֶיךָ;
וּרְכַב וּצְלַח עַל דַּת אֵמוּן בָּחַרְתָּ;
אָז צַדִּיקִים יוֹדוּ תָּמִיד לִשְׁמֶךָ.

body_plain:
יט. לרעי כאח לי המוכיח במישור לאנשים הנותנים כתף סוררת אל עם ה' בעזבם את תורתו, ואת סכלותם ואת רוע לבבם הראה נגד כל ישראל ונגד השמש

איש מלחמות! תעיר קנאה וזעם
לפני אויב; עליו תתגבר, נצח!
מפחד לא תחת, תשחק לרצח
עליו תרנין אשפה כתרועת רעם.

לקראת נשק תצא, וכהולם פעם
הכה תכה תמחץ ראש חזקי מצח;
יאדימו כתולע, יבשו נצח,
כי המירו חקם, וישנו טעם.

נפת ודבש תטפנה שפתותיך;
ולפי בוזי אל חי מחסם שמרת;
גדול עשית לך שם תפארתך.

על במותם תדרך, תרדף קמיך;
ורכב וצלח על דת אמון בחרת;
אז צדיקים יודו תמיד לשמך.

body_nikkud:
לז. מי זה האיש שמח בחלקו

אֶצְעַד אֶרֶץ לַחְקֹר אֶת דַּרְכֵי גָבֶר,

לָתוּר, לָבוּר אִם עַל חֶלְקוֹ שָׂמֵחַ;

אַבִּיט, אֶרְאֶה אִישׁ אִישׁ מִטּוֹב בֹּרֵחַ

כִּי עַל גֵּווֹ, לֹא עַל נַפְשׁוֹ שָׂם שָׂבֶר.

זֶה יִרְדֹּף הַכָּבוֹד, זֶה יִירָא שָׁבֶר;

זֶה עֹשֶר יִתְאַוֶּה, זֶה הוֹד יָפֵחַ;

זֶה בַשָּׂבָע יִרְעָב, זֶה מַר צֹרֵחַ;

טוֹב מוֹתִי מֵחַיָּי, טוֹב לִי הַקָּבֶר.
זֶה בַּשַּׁלְוָה יָקוּץ, זֶה נָס מֵחֶרֶב;

זֶה מִזִּקְנָה יִכְאַב, זֶה חַת מִפָּרֶץ;

זֶה בַבֹּקֶר יֹאמַר מִי יִתֵּן עֶרֶב.
פִּי אִישׁ וָאִישׁ אֶשְׁאַל, עֵינַי נָשָׂאתִי

לָדַעַת אִם אֻשַּׁר חֶלְקָם בָּאָרֶץ;

הִנֵּה אֶחָד מֵאֶלֶף לֹא מָצָאתִי.

body_plain:
לז. מי זה האיש שמח בחלקו

אצעד ארץ לחקר את דרכי גבר,

לתור, לבור אם על חלקו שמח;

אביט, אראה איש איש מטוב ברח

כי על גוו, לא על נפשו שם שבר.

זה ירדף הכבוד, זה יירא שבר;

זה עשר יתאוה, זה הוד יפח;

זה בשבע ירעב, זה מר צרח;

טוב מותי מחיי, טוב לי הקבר.
זה בשלוה יקוץ, זה נס מחרב;

זה מזקנה יכאב, זה חת מפרץ;

זה בבקר יאמר מי יתן ערב.
פי איש ואיש אשאל, עיני נשאתי

לדעת אם אשר חלקם בארץ;

הנה אחד מאלף לא מצאתי.

body_nikkud:
סה. לַכֹּל זמן הזה, ועת לכל חפץ

תֹּר הָרִנָּה, עֵת הַזָּמִיר הִגִּיעַ;
בָּא מוֹעֵד הַשִּׂמְחָה, וּזְמַן הַזֶּבֶד,
לֹא נִכָּר שׁוֹעַ לִפְנֵי דַל, אִישׁ כֶּבֶד
עָוֹן עִם אִישׁ צַדִּיק יִשְׁקֹט, יַרְגִּיעַ.

גַּם פֶּתִי גַּם סָכָל אִמְרוֹ יַבִּיעַ;
אִישׁ עָשִׁיר יִתְרוֹמָם עַל בֶּן־יוֹכֶבֶד;
הֵן כָּעָם כַּכֹּהֵן כַּשַּׂר כָּעֶבֶד
מִתְחַכֵּם, מִתְנַשֵּׂא עַד חוּג רָקִיעַ.

אִישׁ אִישׁ מִלִּין יַחְבִּיר עַל סוֹד וָפֶלֶא,
אִישׁ אִישׁ פִּיהוּ יִפְצֶה לִלְשׁוֹנוֹת אָרֶץ;
אִישׁ אִישׁ עַל כֹּל יֹאמַר: מָה־הֵמָּה אֵלֶּה?

הַכֹּל יִדְאֶה הַיּוֹם עַל כַּנְפֵי רוּחַ;
הָאֵד מוֹשֵׁל עַל כֹּל, גֹּדֵר כָּל־פָּרֶץ.
אַשְׁרֵי הָאִישׁ בַּדּוֹר הַזֶּה בָּטוּחַ!

body_plain:
סה. לכל זמן הזה, ועת לכל חפץ

תר הרנה, עת הזמיר הגיע;
בא מועד השמחה, וזמן הזבד,
לא נכר שוע לפני דל, איש כבד
עון עם איש צדיק ישקט, ירגיע.

גם פתי גם סכל אמרו יביע;
איש עשיר יתרומם על בן־יוכבד;
הן כעם ככהן כשר כעבד
מתחכם, מתנשא עד חוג רקיע.

איש איש מלין יחביר על סוד ופלא,
איש איש פיהו יפצה ללשונות ארץ;
איש איש על כל יאמר: מה־המה אלה?

הכל ידאה היום על כנפי רוח;
האד מושל על כל, גדר כל־פרץ.
אשרי האיש בדור הזה בטוח!

body_nikkud:
עא. ביום חתונת ידידי היקר חכם לבב ואמיץ כח כמוהר"ר דוד חנניה ויטרבי עם הכלה המהללה מרת חנה לוריא

הֶאָפֵס לָךְ דָּבָר, אֹהֵב וָרֵעַ?
הַאִם חָכְמָה תִשְׁאַל? הִנֵּה חָכַמְתָּ;
הַאִם כֶּסֶף תַּחְפֹּץ? גַּם זֶה טָעַמְתָּ
לַעְזוֹר עָנִי וָדָל, עָיֵף, יָגֵעַ.

הֶאָפֵס לָךְ דָּבָר, שֵׂכֶל יֹדֵעַ?
הַאֹמֶץ תִּתְאַוֶּה? מִכֹּל עָצַמְתָּ;
אוֹ קוֹל עָרֵב תִּדְרֹשׁ? הִנֵּה נָעַמְתָּ,
כִּי שִׂפְתוֹתֶיךָ מֵי נַחַל נֹבֵעַ.

הֶאָפֵס לָךְ דָּבָר?… אִשָּׁה חָסַרְתָּ;
עַתָּה אוֹתָהּ בִּקַּשְׁתָּ בִּבְלִי דֹפִי,
לֹא עַל מִכְלוֹת זָהָב, לֹא עַל הַצֶּבִי.

אֶל יִרְאַת אֵל תִּפְנֶה, אוֹתָהּ בָּחַרְתָּ;
שֶׁקֶר הַחֵן תַּחְשֹׁב, הֶבֶל הַיֹּפִי;
עָלִיתָ לַמָּרוֹם. שָׁבִיתָ שֶׁבִי.

body_plain:
עא. ביום חתונת ידידי היקר חכם לבב ואמיץ כח כמוהר"ר דוד חנניה ויטרבי עם הכלה המהללה מרת חנה לוריא

האפס לך דבר, אהב ורע?
האם חכמה תשאל? הנה חכמת;
האם כסף תחפץ? גם זה טעמת
לעזור עני ודל, עיף, יגע.

האפס לך דבר, שכל ידע?
האמץ תתאוה? מכל עצמת;
או קול ערב תדרש? הנה נעמת,
כי שפתותיך מי נחל נבע.

האפס לך דבר?… אשה חסרת;
עתה אותה בקשת בבלי דפי,
לא על מכלות זהב, לא על הצבי.

אל יראת אל תפנה, אותה בחרת;
שקר החן תחשב, הבל היפי;
עלית למרום. שבית שבי.

body_nikkud:
עט. ועת שלום

יוֹם שָׂשׂוֹן, יוֹם שִׂמְחָה וּזְמַן תּוֹחֶלֶת
כִּי קוֹל שָׁלוֹם וּמְבַשֵּׂר טוֹב בָּאָרֶץ;
תַּחַת מַלְכוּת זָדוֹן קָמָה מֶמְשֶׁלֶת
אַחְוָה, חֶדְוָה, שַׁלְוָה, שָׁבַת כָּל קָרֶץ.

שֵׂכֶל הֵרִים נִסּוּ, בּוֹשָׁה אִוֶּלֶת;
בִּרְחוֹבוֹתֵינוּ אֵין יוֹצֵאת אֵין פָּרֶץ;
אִישׁ אִישׁ לֹא יֵחַת, לֹא יִסְגֹּר הַדֶּלֶת,
כִּי לִדְבַשׁ נֶהְפַּךְ רֹאשׁ פֶּתֶן וָשָׁרֶץ.

דִּבְרֵי שָׁלוֹם נִשְׁמַע מִנִּי כָל עֵבֶר;
שָׁלוֹם יִשְׁאַל, שָׁלוֹם יָשִׁיב הָרֵעַ,
שָׁלוֹם שָׁלוֹם יִקְצֹר, שָׁלוֹם זֹרֵעַ.

בֶּטַח תַּחַת גַּפְנוֹ יֵשֵׁב כָּל גֶּבֶר;
דֹּב יָגוּר עִם פָּרָה, אַרְיֵה עִם כֶּשֶׂב;
הַר יָרֹן, עֵץ יָגִיל, יִשְׂחַק כָּל עֵשֶׂב.

body_plain:
עט. ועת שלום

יום ששון, יום שמחה וזמן תוחלת
כי קול שלום ומבשר טוב בארץ;
תחת מלכות זדון קמה ממשלת
אחוה, חדוה, שלוה, שבת כל קרץ.

שכל הרים נסו, בושה אולת;
ברחובותינו אין יוצאת אין פרץ;
איש איש לא יחת, לא יסגר הדלת,
כי לדבש נהפך ראש פתן ושרץ.

דברי שלום נשמע מני כל עבר;
שלום ישאל, שלום ישיב הרע,
שלום שלום יקצר, שלום זרע.

בטח תחת גפנו ישב כל גבר;
דב יגור עם פרה, אריה עם כשב;
הר ירן, עץ יגיל, ישחק כל עשב.

body_nikkud:
               מרגיזי פניך אֵל יעקב סלה

זֶה      דוֹר סוֹרֵר, מֹרֶה, וּמְלֵא כָל-מָעַל;
         דּוֹר נָבָל, לֹא חָכָם; דּוֹר שֹׁד וָשֶׁבֶר;
         דּוֹר לֹא הֵכִין לִבּוֹ אֶל אֵל מִמָּעַל;
         דּוֹר עַז פָּנִים, קָשֶׁה מִנִּי כָל-עֵבֶר.
בָּעֵת הַזֹּאת קֻבַּעַת כּוֹס הָרָעֲל
         הֵן בִּשְׂמָחוֹת וָגִיל יִשְׁתֶּה כָל-גֶּבֶר;
         כָּל-אִישׁ וָאִישׁ יִכְרַע לִפְנֵי הַבָּעֲל,
         כִּי בַּכֶּסֶף יָשִׂים תִּקְוָה וָשֶׂבֶר.
אוֹי נָא לָנוּ! כִּמְעַט כִסְדֹם הָיִינוּ;
         פֶּרֶץ וָרִיב נִשְׁמַע בִּרְחֹבֹתֵינוּ,
         כִּי מִדֶּרֶךְ הַטּוֹב לֵבָב פָּנִינוּ.
רֹעֶה יִשְׂרָאֵל, נָא, רַחֵם עָלֵינוּ;
         אִם כֻלָּנוּ כַצֹאן אֶתְמוֹל תָּעִינוּ,
         פָּנֶיךָ אַל תַּסְתֵּר הַיּוֹם מִמֶּנוּ.

body_plain:
               מרגיזי פניך אל יעקב סלה

זה      דור סורר, מרה, ומלא כל-מעל;
         דור נבל, לא חכם; דור שד ושבר;
         דור לא הכין לבו אל אל ממעל;
         דור עז פנים, קשה מני כל-עבר.
בעת הזאת קבעת כוס הרעל
         הן בשמחות וגיל ישתה כל-גבר;
         כל-איש ואיש יכרע לפני הבעל,
         כי בכסף ישים תקוה ושבר.
אוי נא לנו! כמעט כסדם היינו;
         פרץ וריב נשמע ברחבתינו,
         כי מדרך הטוב לבב פנינו.
רעה ישראל, נא, רחם עלינו;
         אם כלנו כצאן אתמול תעינו,
         פניך אל תסתר היום ממנו.

body_nikkud:
               אשר הלך חשכים ונחם על הרעה

צַדִּיק      אֲדֹנָי הוּא, וּפִיו מָרִיתִי;
          חָמָס, מְרִי, זָדוֹן, וְחֵטְא אָהָבְתִּי;
          עֵדוֹת וְתוֹרַת אֵל אֲנִי עָזָבְתִּי;
          אוֹיָה! כְּשֶׂה אֹבֵד הֲלֹא תָעִיתִי.
חֻקִּים וּמִשְׁפָּטִים אֲנִי בָזִיתִי;
          עַל קִיא כְכֶלֶב עַל עֲוֹנִי שָׁבְתִּי;
          עָוֶל בְּכַּפַּי יֵשׁ, וְרִיב חֹבָבְתִּי;
          קַצְתִּי בְחַיַּי עַל אֲשֶׁר עָשִׂיתִי.
דִּבְרֵי עֲוֹנוֹת גָּבְרוּ מִסֵּפֶר,
          בּשְׁתִּי אֱלֹהַי, הָהּ! וְגַם נִכְלָמְתִּי –
          אֵין עוֹד בְּפִי מִלָּה – אֲהָהּ! נִפְעָמְתִּי.
אֵשֵׁב בְּצוֹם וּבְכִי, וְשַׂק וָאֵפֶר;
          אוֹדֶה עֲלֵי פִשְׁעִי אֲשֶׁר אָשָׁמְתִּי,
          כִּי אַחֲרֵי שׁוּבִי הֲלֹא נִחָמְתִּי.

body_plain:
               אשר הלך חשכים ונחם על הרעה

צדיק      אדני הוא, ופיו מריתי;
          חמס, מרי, זדון, וחטא אהבתי;
          עדות ותורת אל אני עזבתי;
          אויה! כשה אבד הלא תעיתי.
חקים ומשפטים אני בזיתי;
          על קיא ככלב על עוני שבתי;
          עול בכפי יש, וריב חבבתי;
          קצתי בחיי על אשר עשיתי.
דברי עונות גברו מספר,
          בשתי אלהי, הה! וגם נכלמתי –
          אין עוד בפי מלה – אהה! נפעמתי.
אשב בצום ובכי, ושק ואפר;
          אודה עלי פשעי אשר אשמתי,
          כי אחרי שובי הלא נחמתי.

body_nikkud:
               אשר פחד קראהו ורעדה, וקורא אל ה' אולי ישוב
               מחרון אפו ולא יאבד.

אִם      אֶשְׁכְּבָה, אִם אֵשְׁבָה צָפֹנָה,
         עֵינִי מְקוֹר דִּמְעָה עֲלֵי מַלְקֹחַ;
         אִם מַעֲרָב אֶסֹּב אֲזַי תָּבֹאנָה
         כָּל מַחְשְׁבוֹת לִבִּי כְּקוֹץ וָחוֹחַ;
אִם אֶל פְּאַת מִזְרָח אֲנִי אֶצְפֹּנָה,
         אֵין לִי מְעַט שַׁלְוָה וְאֵין מָנוֹחַ;
         אוֹ אִם לְדָרֹם אֵרְדָה, אֶשְׁכֹּנָה,
         אֶהְיֶה כְּאִישׁ נִדְהָם וְאָפֵס כֹּחַ.
עַל רֹב עֲוֹנוֹתַי מְאֹד דַּלוֹתִי;
         הַשְׁקֵט אֲבַקֵּשׁ פֹּה, וּּפֹה אֵין נָחַת,
         מִכֹּה שְׁאוֹל אֶרְאֶה, וּמִכֹּה שָׁחַת.
אוֹי לִי! בְּכָל-פִּנָּה אֲנִי שַׁחוֹתִי;
         אַבִּיט וְאֵין עֹזֵר לְהַצִּילֵנִי,
         אִם לֹא יְרַחֵם אֵל לְהוֹשִׁיעֵנִי.

body_plain:
               אשר פחד קראהו ורעדה, וקורא אל ה' אולי ישוב
               מחרון אפו ולא יאבד.

אם      אשכבה, אם אשבה צפנה,
         עיני מקור דמעה עלי מלקח;
         אם מערב אסב אזי תבאנה
         כל מחשבות לבי כקוץ וחוח;
אם אל פאת מזרח אני אצפנה,
         אין לי מעט שלוה ואין מנוח;
         או אם לדרם ארדה, אשכנה,
         אהיה כאיש נדהם ואפס כח.
על רב עונותי מאד דלותי;
         השקט אבקש פה, ופה אין נחת,
         מכה שאול אראה, ומכה שחת.
אוי לי! בכל-פנה אני שחותי;
         אביט ואין עזר להצילני,
         אם לא ירחם אל להושיעני.

body_nikkud:
               אותו לא אוכל.

גֵאֶה, רְחַב לֵבָב, גְּבַהּ עֵינָיִם.
         בּוֹר רֵיק, וְנֹאד קִיטוֹר, וְסִיר נָפוּחַ;
         פַּרְעֹה זְכוֹר, הָמָן, וְאִישׁ בֵּינָיִם
         הָרָה חֳרִי, עָמָל, וְיָלַד רוּחַ.
חוּשָׁה, פְּנֵה אֵלַי, וְהַט אָזְנָיִם;
         אֶת כָּל-דְּבָרַי לָךְ כְּתֹב עַל לוּחַ;
         הַבֵּט בְּקֵץ גֵּאִים, וְאָז מָתְנָיִם
         תַּחְגֹּר לְדַבֵּר טוֹב לְעַנְוֵי רוּחַ.
יָהִיר, שְׁמַע קוֹלִי, נְצֹר דַּרְכְּךָ
         מִתִּימֲרוֹת עָשָׁן מְכַלּוֹת עָיִן;
         מִקִּרְבְּךָ הָסֵר זְדוֹן לִבֶּךָ.
מִי לָךְ, וּמַה-לָךְ פֹּה, פְּקַח עֵינֶיךָ!
         אַתָּה כְאִישׁ שִׁכּוֹר עֲבָרוֹ יָיִן;
         רוּחַ, נְשִׂיאִים לָךְ, וְגֶשֶׁם אָיִן.

body_plain:
               אותו לא אוכל.

גאה, רחב לבב, גבה עינים.
         בור ריק, ונאד קיטור, וסיר נפוח;
         פרעה זכור, המן, ואיש בינים
         הרה חרי, עמל, וילד רוח.
חושה, פנה אלי, והט אזנים;
         את כל-דברי לך כתב על לוח;
         הבט בקץ גאים, ואז מתנים
         תחגר לדבר טוב לענוי רוח.
יהיר, שמע קולי, נצר דרכך
         מתימרות עשן מכלות עין;
         מקרבך הסר זדון לבך.
מי לך, ומה-לך פה, פקח עיניך!
         אתה כאיש שכור עברו יין;
         רוח, נשיאים לך, וגשם אין.

body_nikkud:
אִישׁ אֲשֶׁר לֹא רָגַל עַל לְשׁוֹנוֹ,
אִם שְׂעָרוֹ יַעַד פְּרָחִים וְאִם לֹא;

אֲשֶׁר נַפְשׁוֹ הוּא הִכְנִיעַ,
אִם מַחְלָפוֹת לְרֹאשׁוֹ וְאִם לֹא;

אֲשֶׁר אֵשֶׁת רֵעוֹ יֵרֶא וְלֹא יַחְמֹד,
אִם בְּאֵפֶר מָרַח בְּשָׂרוֹ וְאִם לֹא;

וַאֲשֶׁר עִוֵּר הוּא לְעשֶׁר זָרִים,
וְאִם עֵינָיו אוֹרוֹת מִן הַשֶּׁמֶשׁ;

וַאֲשֶׁר חֵרֵשׁ הוּא לְמִשְׁפַּט זָרִים,
וְאִם תֵּטִיב אָזְנוֹ שְׁמֹעַ מִן הַשּׁוּעָל –

הוּא הוּא, תּוּקָא, צַדִּיק תָּמִים.

body_plain:
איש אשר לא רגל על לשונו,
אם שערו יעד פרחים ואם לא;

אשר נפשו הוא הכניע,
אם מחלפות לראשו ואם לא;

אשר אשת רעו ירא ולא יחמד,
אם באפר מרח בשרו ואם לא;

ואשר עור הוא לעשר זרים,
ואם עיניו אורות מן השמש;

ואשר חרש הוא למשפט זרים,
ואם תטיב אזנו שמע מן השועל –

הוא הוא, תוקא, צדיק תמים.

body_nikkud:
הוֹי, אָחִי הַיָּקָר, אַל תִּשְׁאַל עוֹד אוֹתִי:
מַדּוּעַ עַל סְבִיבַי כֹּה אַבִּיט בְּלֵאוּת;
מַדּוּעַ מֶבָּטִי כֹּה קוֹדֵר; לֹא אָשִׁית
אֶת לִבִּי לְאַהֲבָה וּלְרֵעוּת?

אַל תִּשְׁאַל: מַדּוּעַ לֹא תֵדַע צְחֹק שְׂפָתִי;
בְּמִצְחִי הַצָּעִיר כֹּה רַבִּים הַקְּמָטִים;
מַדּוּעַ אֵין דָּם עוֹד בְּפָנַי הַחִוְרִים? –
אַל תִּשְׁאַל לְאֵלֶּה הַפְּרָטִים!

שְׁאַל אָחִי אוֹתִי: מַדּוּעַ עוֹד אַרְגִּישׁ;
זִיק חַיִּים, אִם אֶחָד, בְּעוֹרְקַי מִתְנוֹצֵץ;
מְקוֹר דִּמְעָה מַדּוּעַ לֹא נִסְכַּר עֲדֶנָּה;
מַדּוּעַ הַלֵּב לֹא יִתְפּוֹצֵץ?! –

הצפה, ט' אב, תרס"ג

body_plain:
הוי, אחי היקר, אל תשאל עוד אותי:
מדוע על סביבי כה אביט בלאות;
מדוע מבטי כה קודר; לא אשית
את לבי לאהבה ולרעות?

אל תשאל: מדוע לא תדע צחק שפתי;
במצחי הצעיר כה רבים הקמטים;
מדוע אין דם עוד בפני החורים? –
אל תשאל לאלה הפרטים!

שאל אחי אותי: מדוע עוד ארגיש;
זיק חיים, אם אחד, בעורקי מתנוצץ;
מקור דמעה מדוע לא נסכר עדנה;
מדוע הלב לא יתפוצץ?! –

הצפה, ט' אב, תרס"ג

body_nikkud:
אַל תִּשְׁאַל עוֹד אוֹתִי: מַדּוּעַ נֶעֱצַבְתִּי?
מַדּוּעַ עַל סְבִיבַי כֹּה אַבִּיט בְּלֵאוּת;
מַדּוּעַ מֶבָּטִי כֹה קוֹדֵר; לֹא אָשִׁית
אֶת לִבִּי לְאַהֲבָה וּלְרֵעוּת?

אַל תִּשְׁאַל: מַדּוּעַ לֹא תֵּדַע צְחוֹק שְׂפָתִי;
בְּמִצְחִי הַצָּעִיר כֹּה רַבִּים הַקְּמָטִים;
מַדּוּעַ אֵין דָּם עוֹד בְּפָנַי הַחִוְּרִים? –
אַל תִּשְׁאַל לְאֵלֶּה הַפְּרָטִים!

שְׁאַל אוֹתִי: אֵיךְ אֲנִי חָל עוֹד וּמַרְגִישׁ?
זִיק חַיִּים בְּעֵינַי אֵיכָכָה מִתְנוֹצֵץ;
מְקוֹר דִּמְעָה מַדּוּעַ לֹא נִסְכַּר עֲדֶנָּה;
מַדּוּעַ הַלֵּב לֹא יִתְפּוֹצֵץ?

body_plain:
אל תשאל עוד אותי: מדוע נעצבתי?
מדוע על סביבי כה אביט בלאות;
מדוע מבטי כה קודר; לא אשית
את לבי לאהבה ולרעות?

אל תשאל: מדוע לא תדע צחוק שפתי;
במצחי הצעיר כה רבים הקמטים;
מדוע אין דם עוד בפני החורים? –
אל תשאל לאלה הפרטים!

שאל אותי: איך אני חל עוד ומרגיש?
זיק חיים בעיני איככה מתנוצץ;
מקור דמעה מדוע לא נסכר עדנה;
מדוע הלב לא יתפוצץ?

body_nikkud:
כִּי פְנֵי הַשָּׁמַיִם בִּתְכוֹל זָהֲרוּ –
וְאָפְקָם כִּי אָדַם;
כִּי הוֹרִיקוּ פְנֵיהֶן הַשְּׁדֵמוֹת –
וַיֶּרֶב יְבוּלָן;
כִּי שָׁקְטוּ לְבָבוֹת כְּאוּבִים –
וַיָּפָג עִצְּבוֹנָם;
כִּי רָגְעוּ חֲלוֹמוֹת נִסְעָרִים –

אֹמַר כִּי טוֹב!

body_plain:
כי פני השמים בתכול זהרו –
ואפקם כי אדם;
כי הוריקו פניהן השדמות –
וירב יבולן;
כי שקטו לבבות כאובים –
ויפג עצבונם;
כי רגעו חלומות נסערים –

אמר כי טוב!

body_nikkud:
לוּ יָדַעְתִּי הַבַּע
אֶת אֲשֶׁר לֹא נִתַּן לִי;
לוּ יָדַעְתִּי עַצֵּב
אֲשֶׁר בִּי מִתְקוֹמֵם;
לוּ יָדַעְתִּי זַמֵּר
אֶת הַלַּחַן שֶׁרָן בִּי;
לוּ יָדַעְתִּי הַחֲרֵשׁ
קַשּׁוּב וְאִלֵּם…

13.2.46

body_plain:
לו ידעתי הבע
את אשר לא נתן לי;
לו ידעתי עצב
אשר בי מתקומם;
לו ידעתי זמר
את הלחן שרן בי;
לו ידעתי החרש
קשוב ואלם…

13.2.46

body_nikkud:
אֵלִי, גַּלֵּה בַּת אַהֲבָתִי,
נַפְשִׁי הוֹמָה: בַּת אַהֲבָתִי!
צִיצֵי אִבִּי רַכִּים נוֹבְלִים
כְּמֵהֵי טַלָּם – בַּת אַהֲבָתִי;
שְׂפָתַי צְרוּבוֹת, מֻכּוֹת שָׁרָב,
עֵין עֶרְגָּתָם – בַּת אַהֲבָתִי;
לִבִּי כָלֶה אַט וְנָמֵק
מֵעֲרוֹג אֶל בַּת אַהֲבָתִי;
בְּשַׁחַר יוֹמִי אֶכְבֶּה, אֵלִי,
אִם לֹא תָחִישׁ בַּת אַהֲבָתִי.

body_plain:
אלי, גלה בת אהבתי,
נפשי הומה: בת אהבתי!
ציצי אבי רכים נובלים
כמהי טלם – בת אהבתי;
שפתי צרובות, מכות שרב,
עין ערגתם – בת אהבתי;
לבי כלה אט ונמק
מערוג אל בת אהבתי;
בשחר יומי אכבה, אלי,
אם לא תחיש בת אהבתי.

body_nikkud:
הַדֹּאַר רָץ וְקָרֵב שָׁם;
מַה תֶּהֱמֶה, תִּגְעַשׁ בִּי כַּיָּם – הַלֵּב?
הַדֹּאַר כְּלוּם לֹא הֵבִיא לִי;
וּמַה תִּתְרוֹצֵץ, תִּקְפָּץ בִּי – הַלֵּב?
אָכֵן הַדֹּאַר בָּא מִמְקוֹם,
שָׁם הָיְתָה לָךְ אֲהוּבַת תֹּם – הַלֵּב;
וְהִנְּךָ רָץ לִשְׁאֹל לַבָּא,
מַה נִּשְׁמַע שָׁם, הֲשָׁלוֹם לָהּ – הַלֵּב!

מלחין: פרנץ שוברט

body_plain:
הדאר רץ וקרב שם;
מה תהמה, תגעש בי כים – הלב?
הדאר כלום לא הביא לי;
ומה תתרוצץ, תקפץ בי – הלב?
אכן הדאר בא ממקום,
שם היתה לך אהובת תם – הלב;
והנך רץ לשאל לבא,
מה נשמע שם, השלום לה – הלב!

מלחין: פרנץ שוברט
